        long eventCount = reconcile(input, (account, state) -> summaries.add(state.summary()));
        summaries.sort(Comparator.comparing(AccountSummary::account));
        return new Report(eventCount, summaries);
    }

    public static long reconcile(Path input, Path report) throws IOException {
        try (BufferedWriter writer = Files.newBufferedWriter(report, StandardCharsets.UTF_8)) {
            return reconcile(input, new SummaryWriter(writer));
        }
    }

    @FunctionalInterface
    private interface SummaryConsumer {
        void accept(String account, AccountState state) throws IOException;
    }

    private static long reconcile(Path input, SummaryConsumer consumer) throws IOException {
        Path work = Files.createTempDirectory("ledger-reconcile-");
        DataOutputStream[] buckets = new DataOutputStream[BUCKET_COUNT];
        long eventCount = 0;
        long previous = -1;
        try {
            try (EventLog.StreamReader reader = new EventLog.StreamReader(input)) {
                while (reader.next()) {
                    long sequence = reader.sequence();
                    if (sequence <= previous) {
                        throw new IllegalArgumentException("sequence order at line " + reader.lineNumber());
                    }
                    previous = sequence;
                    eventCount++;
                    String account = reader.account();
                    int bucket = (account.hashCode() & 0x7fffffff) % BUCKET_COUNT;
                    if (buckets[bucket] == null) {
                        buckets[bucket] = newBucket(work.resolve("bucket-" + bucket + ".bin"));
                    }
                    writeEvent(buckets[bucket], account, reader.timestamp(), sequence, reader.amount());
                }
            }
            if (eventCount == 0) {
                throw new IllegalArgumentException("empty log");
            }

            List<Path> summaryFiles = new ArrayList<>();
            try {
                for (int bucket = 0; bucket < BUCKET_COUNT; bucket++) {
                    Path source = work.resolve("bucket-" + bucket + ".bin");
                    if (!Files.exists(source)) {
                        continue;
                    }
                    Path summary = work.resolve("summary-" + bucket + ".bin");
                    summarizeBucket(source, summary);
                    summaryFiles.add(summary);
                }
                writeReport(report, eventCount, summaryFiles);
            } finally {
                for (Path summary : summaryFiles) {
                    Files.deleteIfExists(summary);
                }
            }
            return eventCount;
        } finally {
            for (DataOutputStream output : buckets) {
                if (output != null) {
                    output.close();
                }
            }
            for (int bucket = 0; bucket < BUCKET_COUNT; bucket++) {
                Files.deleteIfExists(work.resolve("bucket-" + bucket + ".bin"));
            }
            deleteTree(work);
        }
    }

    private static DataOutputStream newBucket(Path path) throws IOException {
        return new DataOutputStream(new BufferedOutputStream(
                Files.newOutputStream(path, StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE),
                64 * 1024));
    }

    private static void writeEvent(DataOutputStream output, String account,
                                   long timestamp, long sequence, long amount) throws IOException {
        output.writeLong(timestamp);
        output.writeLong(sequence);
        output.writeLong(amount);
        byte[] name = account.getBytes(StandardCharsets.US_ASCII);
        output.writeByte(name.length);
        output.write(name);
    }

    private static void summarizeBucket(Path source, Path summaryPath) throws IOException {
        List<Path> runs = new ArrayList<>();
        try (DataInputStream input = new DataInputStream(Files.newInputStream(source))) {
            EventRecord[] chunk = new EventRecord[CHUNK_RECORDS];
            int count = readChunk(input, chunk, 0);
            if (count < CHUNK_RECORDS) {
                Arrays.sort(chunk, 0, count, RECORD_ORDER);
                try (SummaryOutput output = new SummaryOutput(summaryPath)) {
                    processRecords(chunk, count, output);
                }
                return;
            }

            int runNumber = 0;
            while (count > 0) {
                Arrays.sort(chunk, 0, count, RECORD_ORDER);
                Path run = source.resolveSibling(source.getFileName() + ".run" + runNumber++);
                try (DataOutputStream output = newBucket(run)) {
                    for (int i = 0; i < count; i++) {
                        EventRecord record = chunk[i];
                        writeEvent(output, record.account, record.timestamp,
                                record.sequence, record.amount);
                    }
                }
                runs.add(run);
                count = readChunk(input, chunk, 0);
            }
        }

        try (SummaryOutput output = new SummaryOutput(summaryPath)) {
            if (runs.size() == 1) {
                try (RunReader reader = new RunReader(runs.get(0))) {
                    EventRecord record;
                    while ((record = reader.next()) != null) {
                        output.accept(record);
                    }
                }
            } else {
                mergeRuns(runs, output);
            }
        } finally {
            for (Path run : runs) {
                Files.deleteIfExists(run);
            }
        }
    }

    private static int readChunk(DataInputStream input, EventRecord[] chunk, int offset) throws IOException {
        int count = offset;
        try {
            while (count < chunk.length) {
                chunk[count++] = readRecord(input);
            }
        } catch (EOFException ignored) {
            // A partial record is an actual corruption and is rethrown by readRecord.
        }
        return count;
    }

    private static EventRecord readRecord(DataInputStream input) throws IOException {
        long timestamp = input.readLong();
        long sequence = input.readLong();
        long amount = input.readLong();
        int length = input.readUnsignedByte();
        byte[] name = new byte[length];
        input.readFully(name);
        return new EventRecord(new String(name, StandardCharsets.US_ASCII), timestamp, sequence, amount);
    }

    private static void processRecords(EventRecord[] records, int count,
                                       SummaryOutput output) throws IOException {
        AccountState state = null;
        for (int i = 0; i < count; i++) {
            EventRecord record = records[i];
            if (state == null || !state.account.equals(record.account)) {
                if (state != null) {
                    output.accept(state);
                }
                state = new AccountState(record.account);
            }
            state.apply(record.sequence, record.timestamp, record.amount);
        }
        if (state != null) {
            output.accept(state);
        }
    }

    private static void mergeRuns(List<Path> runs, SummaryOutput output) throws IOException {
        PriorityQueue<RunReader> queue = new PriorityQueue<>(runs.size(),
                Comparator.comparing(RunReader::peek));
        try {
            for (Path run : runs) {
                RunReader reader = new RunReader(run);
                if (reader.next() != null) {
                    queue.add(reader);
                } else {
                    reader.close();
                }
            }
            while (!queue.isEmpty()) {
                RunReader reader = queue.poll();
                output.accept(reader.current());
                if (reader.next() != null) {
                    queue.add(reader);
                } else {
                    reader.close();
                }
            }
        } finally {
            for (RunReader reader : queue) {
                reader.close();
            }
        }
    }

    private static void writeReport(Path report, long eventCount, List<Path> summaryFiles)
            throws IOException {
        try (BufferedWriter writer = Files.newBufferedWriter(report, StandardCharsets.UTF_8)) {
            writer.write("events|");
            writer.write(Long.toString(eventCount));
            writer.write('\n');
            PriorityQueue<SummaryReader> queue = new PriorityQueue<>(summaryFiles.size(),
                    Comparator.comparing(SummaryReader::peek));
            try {
                for (Path summary : summaryFiles) {
                    SummaryReader reader = new SummaryReader(summary);
                    if (reader.next()) {
                        queue.add(reader);
                    } else {
                        reader.close();
                    }
                }
                while (!queue.isEmpty()) {
                    SummaryReader reader = queue.poll();
                    writer.write(reader.account());
                    writer.write('|');
                    writer.write(Long.toString(reader.count()));
                    writer.write('|');
                    writer.write(Long.toString(reader.total()));
                    writer.write('|');
                    writer.write(Long.toString(reader.firstSequence()));
                    writer.write('|');
                    writer.write(Long.toString(reader.lastSequence()));
                    writer.write('|');
                    writer.write(Long.toString(reader.firstTimestamp()));
                    writer.write('|');
                    writer.write(Long.toString(reader.lastTimestamp()));
                    writer.write('|');
                    writer.write(Long.toString(reader.checksum()));
                    writer.write('\n');
                    if (reader.next()) {
                        queue.add(reader);
                    } else {
                        reader.close();
                    }
                }
            } finally {
                for (SummaryReader reader : queue) {
                    reader.close();
                }
            }
        }
    }

    private static void deleteTree(Path path) throws IOException {
        if (Files.isDirectory(path)) {
            try (var entries = Files.list(path)) {
                for (Path entry : entries.toList()) {
                    deleteTree(entry);
                }
            }
        }
        Files.deleteIfExists(path);
    }

    private static final class SummaryOutput implements Closeable {
        private final DataOutputStream output;

        private SummaryOutput(Path path) throws IOException {
            output = new DataOutputStream(new BufferedOutputStream(
                    Files.newOutputStream(path, StandardOpenOption.CREATE,
                            StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE),
                    64 * 1024));
        }

        private void accept(EventRecord ignored) {
            throw new AssertionError("records cannot be written as summaries");
        }

        private void accept(AccountState state) throws IOException {
            AccountSummary summary = state.summary();
            byte[] account = summary.account().getBytes(StandardCharsets.US_ASCII);
            output.writeByte(account.length);
            output.write(account);
            output.writeLong(summary.count());
            output.writeLong(summary.total());
            output.writeLong(summary.firstSequence());
            output.writeLong(summary.lastSequence());
            output.writeLong(summary.firstTimestamp());
            output.writeLong(summary.lastTimestamp());
            output.writeLong(summary.checksum());
        }

        @Override
        public void close() throws IOException {
            output.close();
        }
    }

    private static final class RunReader implements Closeable {
        private final DataInputStream input;
        private EventRecord current;

        private RunReader(Path path) throws IOException {
            input = new DataInputStream(Files.newInputStream(path));
        }

        private EventRecord peek() {
            return current;
        }

        private EventRecord current() {
            return current;
        }

        private EventRecord next() throws IOException {
            try {
                current = readRecord(input);
                return current;
            } catch (EOFException ignored) {
                current = null;
                return null;
            }
        }

        @Override
        public void close() throws IOException {
            input.close();
        }
    }

    private static final class Summary {
        private String account;
        private long count;
        private long total;
        private long firstSequence;
        private long lastSequence;
        private long firstTimestamp;
        private long lastTimestamp;
        private long checksum;
    }

    private static final class SummaryReader implements Closeable {
        private final DataInputStream input;
        private final Summary current = new Summary();

        private SummaryReader(Path path) throws IOException {
            input = new DataInputStream(Files.newInputStream(path));
        }

        private String peek() {
            return current.account;
        }

        private boolean next() throws IOException {
            try {
                int length = input.readUnsignedByte();
                byte[] account = new byte[length];
                input.readFully(account);
                current.account = new String(account, StandardCharsets.US_ASCII);
                current.count = input.readLong();
                current.total = input.readLong();
                current.firstSequence = input.readLong();
                current.lastSequence = input.readLong();
                current.firstTimestamp = input.readLong();
                current.lastTimestamp = input.readLong();
                current.checksum = input.readLong();
                return true;
            } catch (EOFException ignored) {
                current.account = null;
                return false;
            }
        }

        private String account() {
            return current.account;
        }

        private long count() {
            return current.count;
        }

        private long total() {
            return current.total;
        }

        private long firstSequence() {
            return current.firstSequence;
        }

        private long lastSequence() {
            return current.lastSequence;
        }

        private long firstTimestamp() {
            return current.firstTimestamp;
        }

        private long lastTimestamp() {
            return current.lastTimestamp;
        }

        private long checksum() {
            return current.checksum;
        }

        @Override
        public void close() throws IOException {
            input.close();
        }
    }

    private static final class SummaryWriter implements SummaryConsumer {
        private final BufferedWriter writer;

        private SummaryWriter(BufferedWriter writer) {
            this.writer = writer;
        }

        @Override
        public void accept(String account, AccountState state) throws IOException {
            writer.write(state.summary().toString());
            writer.write('\n');
        }
    }

    private Reconciler() {
    }
