                current.firstSequence = input.readLong();
                current.lastSequence = input.readLong();
                current.firstTimestamp = input.readLong();
                current.lastTimestamp = input.readLong();
                current.checksum = input.readLong();
                return true;
            } catch (EOFException ignored) {
                current.account = null;
                return false;
            }
        }

        private String account() {
            return current.account;
        }

        private long count() {
            return current.count;
        }

        private long total() {
            return current.total;
        }

        private long firstSequence() {
            return current.firstSequence;
        }

        private long lastSequence() {
            return current.lastSequence;
        }

        private long firstTimestamp() {
            return current.firstTimestamp;
        }

        private long lastTimestamp() {
            return current.lastTimestamp;
        }

        private long checksum() {
            return current.checksum;
        }

        @Override
        public void close() throws IOException {
            input.close();
        }
    }

    private Reconciler() {
    }
